mapper.select:
SELECT s.SUPPLIER_ID, s.SUPPLIER_CODE, s.SUPPLIER_NAME, s.SUPPLIER_CATEGORY, s.SUPPLIER_STATUS, s.CREDIT_CODE, s.LEGAL_REPRESENTATIVE, s.REGISTERED_ADDRESS, s.CONTACT_PERSON, s.CONTACT_PHONE, s.CONTACT_EMAIL, s.FAX_NUMBER, s.CONTACT_ADDRESS, s.BANK_NAME, s.BANK_ACCOUNT, s.CREDIT_LEVEL, s.CREDIT_LIMIT, s.PAYMENT_METHOD, s.PAYMENT_TERMS, s.REMARKS, s.CREATE_TIME, s.CREATE_BY, CASE s.SUPPLIER_CATEGORY WHEN 1 THEN '原材料供应商' WHEN 2 THEN '设备供应商' WHEN 3 THEN '服务供应商' WHEN 4 THEN '其他供应商' ELSE '未知分类' END AS SUPPLIER_CATEGORY_NAME, NVL(SUM(d.REMAINING_AMOUNT), 0) AS PAYABLE_AMOUNT FROM TBL_SUPPLIER s LEFT JOIN TBL_PAYABLE_DOCUMENT d ON s.SUPPLIER_ID = d.SUPPLIER_ID AND d.IS_DELETED = 0 WHERE s.IS_DELETED = 0
AND s.SUPPLIER_CODE LIKE '%' || #{param.supplierCode} || '%'
AND s.SUPPLIER_NAME LIKE '%' || #{param.supplierName} || '%'
AND s.SUPPLIER_CATEGORY = #{param.supplierCategory}
AND s.SUPPLIER_STATUS = #{param.supplierStatus}
AND s.CREDIT_LEVEL = #{param.creditLevel}
AND s.CREDIT_CODE LIKE '%' || #{param.creditCode} || '%'
AND s.CONTACT_PERSON LIKE '%' || #{param.contactPerson} || '%'
AND (s.SUPPLIER_CODE LIKE '%' || #{param.keyword} || '%' OR s.SUPPLIER_NAME LIKE '%' || #{param.keyword} || '%' OR s.CONTACT_PERSON LIKE '%' || #{param.keyword} || '%')
GROUP BY s.SUPPLIER_ID, s.SUPPLIER_CODE, s.SUPPLIER_NAME, s.SUPPLIER_CATEGORY, s.SUPPLIER_STATUS, s.CREDIT_CODE, s.LEGAL_REPRESENTATIVE, s.REGISTERED_ADDRESS, s.CONTACT_PERSON, s.CONTACT_PHONE, s.CONTACT_EMAIL, s.FAX_NUMBER, s.CONTACT_ADDRESS, s.BANK_NAME, s.BANK_ACCOUNT, s.CREDIT_LEVEL, s.CREDIT_LIMIT, s.PAYMENT_METHOD, s.PAYMENT_TERMS, s.REMARKS, s.CREATE_TIME, s.CREATE_BY ORDER BY s.CREATE_TIME DESC

mapper.update:
UPDATE TBL_SUPPLIER
SUPPLIER_CODE = #{supplierCode}, SUPPLIER_NAME = #{supplierName}, SUPPLIER_CATEGORY = #{supplierCategory}, SUPPLIER_STATUS = #{supplierStatus}, CREDIT_CODE = #{creditCode}, LEGAL_REPRESENTATIVE = #{legalRepresentative}, REGISTERED_ADDRESS = #{registeredAddress}, CONTACT_PERSON = #{contactPerson}, CONTACT_PHONE = #{contactPhone}, CONTACT_EMAIL = #{contactEmail}, FAX_NUMBER = #{faxNumber}, CONTACT_ADDRESS = #{contactAddress}, BANK_NAME = #{bankName}, BANK_ACCOUNT = #{bankAccount}, CREDIT_LEVEL = #{creditLevel}, CREDIT_LIMIT = #{creditLimit}, PAYMENT_METHOD = #{paymentMethod}, PAYMENT_TERMS = #{paymentTerms}, REMARKS = #{remarks}, UPDATE_TIME = #{updateTime}, UPDATE_BY = #{updateBy}
WHERE SUPPLIER_ID = #{supplierId} AND IS_DELETED = 0
